      pos++;
      const right = parseTerm();
      result = op === '+' ? result + right : result - right;
    }
    return result;
  };

  const parseTerm = () => {
    let result = parsePower();
    while (pos < tokens.length && (tokens[pos] === '*' || tokens[pos] === '//')) {
      const op = tokens[pos];
      pos++;
      const right = parsePower();
      result = op === '*' ? result * right : Math.floor(result / right);
    }
    return result;
